local function delayCheck(seconds)
    local endAt=os.clock()+seconds
    repeat
        if stopped then return false end
        task.wait(math.max(0.025,math.min(0.13,endAt-os.clock())))
    until os.clock()>=endAt
    return not stopped
end
local function norm(s) return tostring(s or ""):gsub("<[^>]*>",""):lower():gsub("[^%w]","") end
local function txt(n)
    return (n:IsA("TextLabel") or n:IsA("TextButton") or n:IsA("TextBox")) and tostring(n.Text or "") or ""
end
local function vis(n)
    if not n or not n.Parent or not n:IsDescendantOf(pg) then return false end
    local p=n
    while p and p~=pg do
        if p:IsA("ScreenGui") and not p.Enabled then return false end
        if p:IsA("GuiObject") and not p.Visible then return false end
        p=p.Parent
    end
    return true
end
local function midpoint(n) return n.AbsolutePosition+n.AbsoluteSize/2 end
local function moneyIn(t)
    local s=tostring(t or ""):match("%$%s*([%d,]+)")
    return s and tonumber((s:gsub(",",""))) or nil
end
local function getInspect()
    local path=pg:FindFirstChild("Match")
    local inspect=path and path:FindFirstChild("InspectMenu",true)
    if inspect and vis(inspect) then return inspect end
    for _,n in ipairs(pg:GetDescendants()) do
        if norm(n.Name)=="inspectmenu" and vis(n) then return n end
    end
end
local function inspect(unit)
    local root=getInspect()
    if not root then return nil,"InspectMenu closed / unit asleep" end
    local found=false
    local level=nil
    for _,n in ipairs(root:GetDescendants()) do
        if n:IsA("GuiObject") and vis(n) then
            local text=txt(n)
            if norm(text)==norm(unit) then found=true end
            local l=text:match("[Ll][Ee][Vv][Ee][Ll]%s*:?%s*(%d+)")
            if l then level=tonumber(l) end
        end
    end
    if not found then return nil,"wrong unit menu" end
    if not level then return nil,"level unreadable" end
    local button=root:FindFirstChild("UpgradeButton",true)
    if not button or not button:IsA("GuiButton") or not vis(button) then
        return nil,"UpgradeButton missing / menu locked"
    end
    local price,dis=nil,1e9
    local at=midpoint(button)
    for _,n in ipairs(root:GetDescendants()) do
        if n:IsA("GuiObject") and vis(n) then
            local val=moneyIn(txt(n))
            if val then
                local d=(midpoint(n)-at).Magnitude
                if d<350 and d<dis then price,dis=val,d end
            end
        end
    end
    if not price then return nil,"upgrade price unreadable / MAX" end
    return {root=root,button=button,level=level,cost=price}
end
local function cashOnHud(root)
    local c=workspace.CurrentCamera
    local vp=c and c.ViewportSize or Vector2.new(1920,1080)
    local pref=Vector2.new(vp.X*.5,vp.Y*.87)
    local result,dist=nil,1e9
    for _,n in ipairs(pg:GetDescendants()) do
        if (n:IsA("TextLabel") or n:IsA("TextButton")) and vis(n)
            and (not root or not n:IsDescendantOf(root))
            and (not gui or not n:IsDescendantOf(gui)) then
            local raw=txt(n):gsub("%s+","")
            local val=raw:match("^%$([%d,]+)$")
            if val then
                local p=midpoint(n)
                if p.X>vp.X*.3 and p.X<vp.X*.7 and p.Y>vp.Y*.79 and p.Y<vp.Y*.95 then
                    local distance=(p-pref).Magnitude
                    if distance<dist then
                        dist=distance
                        result=tonumber((val:gsub(",","")))
                    end
                end
            end
        end
    end
    return result
end
-- Detect a new match from visible in-game Wave 1 text + the real cash HUD.
-- Wave 1 alone is not sufficient; do not auto-start while still in the lobby.
local function matchActiveWave()
    if not game:IsLoaded() or not getRoot() then return nil end
    if not workspace:FindFirstChild("Troops") then return nil end
    local matchGui=pg:FindFirstChild("Match")
    if not matchGui then return nil end
    local wave=nil
    for _,node in ipairs(matchGui:GetDescendants()) do
        if (node:IsA("TextLabel") or node:IsA("TextButton")) and vis(node) then
            local t=norm(txt(node))
            local n=t:match("^wave0*(%d+)$")
            if n then
                local parsed=tonumber(n)
                if parsed and parsed>=1 then wave=parsed; break end
            end
        end
    end
    if not wave or cashOnHud(nil)==nil then return nil end
    return wave
end
local function matchWaveOneReady()
    return matchActiveWave()==1
end
local function modelLevel(model)
    if not model or not model.Parent then return nil end
    for _,name in ipairs({"Level","level","UpgradeLevel","upgradeLevel"}) do
        local v=model:GetAttribute(name)
        if type(v)=="number" then return v end
    end
    for _,n in ipairs(model:GetDescendants()) do
        if n:IsA("IntValue") or n:IsA("NumberValue") then
            if norm(n.Name)=="level" or norm(n.Name)=="upgradelevel" then
                return tonumber(n.Value)
            end
        elseif n:IsA("TextLabel") then
            local text=txt(n)
            local number=text:match("[Ll][Ee][Vv][Ee][Ll]%s*(%d+)")
            if number then return tonumber(number) end
        end
    end
end
local function modelPos(m)
    local success,where=pcall(function() return m:GetPivot().Position end)
    return success and where or nil
end
local function unitMatches(m,unit)
    return m and m:IsA("Model") and norm(m.Name)==norm(modelNames[unit] or unit)
end
local function worldXZ(p,q)
    return math.sqrt((p.X-q.X)^2+(p.Z-q.Z)^2)
end
local function modelsFor(unit)
    local folder=workspace:FindFirstChild("Troops")
    local out={}
    if folder then
        for _,m in ipairs(folder:GetChildren()) do
            if unitMatches(m,unit) then out[#out+1]=m end
        end
    end
    return out
end
local function knownUnitAlreadyPresent()
    -- Prevent auto-starting in the middle of an existing match.
    -- User can still press START NOW to override this conservative guard.
    for _,unit in ipairs({"pumpkin_farmer","chef_tv_man","medic_cameraman"}) do
        if #modelsFor(unit)>0 then return true end
    end
    return false
end
local function cframeFrom(a)
    if not a or #a~=12 then return nil end
    return CFrame.new(unpack(a))
end
local function cameraAt(t)
    local frames=data.camera
    if #frames==0 then return nil,nil end
    while cameraIndex<#frames-1 and frames[cameraIndex+1][1]<=t do cameraIndex=cameraIndex+1 end
    while cameraIndex>1 and frames[cameraIndex][1]>t do cameraIndex=cameraIndex-1 end
    local first=frames[cameraIndex]
    local second=frames[math.min(cameraIndex+1,#frames)]
    local a,b=cframeFrom(first[2]),cframeFrom(second[2])
    local dt=second[1]-first[1]
    local alpha=dt>0 and math.clamp((t-first[1])/dt,0,1) or 0
    return a:Lerp(b,alpha), first[3]+(second[3]-first[3])*alpha
end
local function setCamera(t,override)
    local c=workspace.CurrentCamera
    if not c then return end
    if c.CameraType~=Enum.CameraType.Scriptable then c.CameraType=Enum.CameraType.Scriptable end
    local cf,fov=cameraAt(t)
    if override then cf=override end
    if cf then c.CFrame=cf end
    if fov then c.FieldOfView=fov end
end
local function refreshReplayCamera()
    if not cameraBound or stopped then return end
    local current=cameraTimeline
    if camMoveDuration>0 then
        local alpha=math.clamp((os.clock()-camMoveWallStart)/camMoveDuration,0,1)
        current=camMoveFrom+(camMoveTo-camMoveFrom)*alpha
    end
    setCamera(cameraFrozen or current,cameraOverride)
end
local function bindCamera()
    cam=workspace.CurrentCamera
    if not cam then return end
    originalCameraType=cam.CameraType
    originalFov=cam.FieldOfView
    cameraIndex=1
    cameraBound=true
    -- Foreground: update immediately before rendering, matching v0.8.4
    -- (Heartbeat-only introduced a possible hit-testing / projection race).
    RunService:BindToRenderStep(cameraBind,Enum.RenderPriority.Camera.Value+20,function()
        if windowFocused then refreshReplayCamera() end
    end)
    -- Background: rendering might be throttled; keep best-effort camera updates.
    local elapsed=0
    cameraConnection=RunService.Heartbeat:Connect(function(dt)
        if not cameraBound or stopped or windowFocused then return end
        elapsed=elapsed+(dt or .03)
        if elapsed<1/15 then return end
        elapsed=0
        refreshReplayCamera()
    end)
end
local function unbindCamera()
    cameraBound=false
    pcall(function() RunService:UnbindFromRenderStep(cameraBind) end)
    if cameraConnection then cameraConnection:Disconnect(); cameraConnection=nil end
    local c=workspace.CurrentCamera
    if c and originalCameraType then c.CameraType=originalCameraType end
    if c and originalFov then c.FieldOfView=originalFov end
end
-- Executor keypress/keyrelease use WINDOWS virtual-key codes (VK),
-- not Enum.KeyCode.Value (which has different numbers for many keys).
local vkCodes={
    W=0x57,A=0x41,S=0x53,D=0x44,
    One=0x31,Two=0x32,Three=0x33,Four=0x34,Five=0x35,
    E=0x45,Q=0x51,R=0x52,F=0x46,
    Space=0x20,LeftShift=0x10,RightShift=0x10,
    LeftControl=0x11,RightControl=0x11,Escape=0x1B,
}
local function sendKey(key,down)
    local enum=Enum.KeyCode[key]
    if not enum then return false,"unknown recorded key "..tostring(key) end
    local attempts={}
    if CONFIG.backgroundMode and not windowFocused then
        if not VIM then return false,"BACKGROUND: VIM missing (no OS keys sent)" end
        local sent,err=pcall(function() VIM:SendKeyEvent(down,enum,false,game) end)
        if sent then return true,"VIM BACKGROUND" end
        return false,"BACKGROUND: VIM rejected key "..tostring(key)..": "..tostring(err)
    end
    if keyboardMode=="AUTO" or keyboardMode=="EXECUTOR" then
        local f=down and keypress or keyrelease
        local vk=vkCodes[key]
        if type(f)=="function" and vk then
            local ok,err=pcall(f,vk)
            if ok then return true,"executor VK "..tostring(vk) end
            attempts[#attempts+1]="executor: "..tostring(err)
        else
            attempts[#attempts+1]="executor VK function/key unavailable"
        end
    end
    if keyboardMode=="AUTO" or keyboardMode=="VIM" then
        if VIM then
            local ok,err=pcall(function() VIM:SendKeyEvent(down,enum,false,game) end)
            if ok then return true,"VirtualInputManager" end
            attempts[#attempts+1]="VIM: "..tostring(err)
        else
            attempts[#attempts+1]="VIM unavailable"
        end
    end
    return false,table.concat(attempts,"; ")
end
local function suspendHeldKeys()
    local a={}
    for key in pairs(keysHeld) do
        local ok=sendKey(key,false)
        if ok then a[#a+1]=key end
    end
    if #a>0 then log("PAUSE HELD KEYS for verified placement/upgrade: "..table.concat(a,",")) end
    return a
end
local function resumeHeldKeys(a)
    if stopped then return end
    for _,key in ipairs(a) do
        if keysHeld[key] then
            local ok,err=sendKey(key,true)
            if not ok then error("cannot resume key "..key..": "..tostring(err)) end
        end
    end
end
-- A full-screen transparent GuiButton catches stray physical clicks while
-- Roblox is focused. A separate high-DisplayOrder GUI keeps the STOP button
-- accessible. During an intentional replay click the shield is briefly hidden.
-- Moving the physical cursor is not intercepted at the OS level.
-- The shield is suspended across placement preparation / click to avoid stealing VIM input.
local function mouseMovementSink(actionName,inputState,inputObject)
    if running and CONFIG.mouseShield and windowFocused and mouseShieldSuspend==0 then
        return Enum.ContextActionResult.Sink
    end
    return Enum.ContextActionResult.Pass
end
updateMouseShield=function()
    local enabled=running and not stopped and CONFIG.mouseShield and windowFocused and mouseShieldSuspend==0
    if mouseShieldGui then
        mouseShieldGui.Enabled=not not enabled
        if mouseShieldSurface then
            mouseShieldSurface.Active=not not enabled
            mouseShieldSurface.Visible=not not enabled
        end
    end
    if mouseShieldButton then
        mouseShieldButton.Text="MOUSE SHIELD: "..(CONFIG.mouseShield and "ON" or "OFF")
        mouseShieldButton.BackgroundColor3=CONFIG.mouseShield
            and Color3.fromRGB(28,130,110) or Color3.fromRGB(96,72,115)
    end
end
local function makeMouseShield()
    mouseShieldGui=Instance.new("ScreenGui")
    mouseShieldGui.Name="LegacyTTD_MouseShield_v0817"
    mouseShieldGui.IgnoreGuiInset=true
    mouseShieldGui.ResetOnSpawn=false
    mouseShieldGui.DisplayOrder=499999 -- BELOW our GUI but ABOVE game UI
    mouseShieldGui.Enabled=false
    mouseShieldGui.Parent=pg
    mouseShieldSurface=Instance.new("TextButton")
    mouseShieldSurface.Name="CatchAccidentalClicks"
    mouseShieldSurface.Size=UDim2.fromScale(1,1)
    mouseShieldSurface.BackgroundTransparency=1
    mouseShieldSurface.Text=""
    mouseShieldSurface.BorderSizePixel=0
    mouseShieldSurface.AutoButtonColor=false
    mouseShieldSurface.Active=true
    mouseShieldSurface.ZIndex=1
    mouseShieldSurface.Parent=mouseShieldGui
    -- IMPORTANT: Do not bind ContextActionService mouse motion here.
    -- That hook was introduced with the placement regression and can interfere
    -- with the game's preview tracking synthetic mouse movement. The optional
    -- GUI intercept alone catches accidental foreground clicks when enabled.
end
local function beginAutoMouseInput()
    local wasUnblocked=mouseShieldSuspend>0
    mouseShieldSuspend=mouseShieldSuspend+1
    updateMouseShield()
    -- Setting ScreenGui.Enabled=false is not guaranteed to update GUI hit-testing
    -- instantly. Wait two scheduler ticks before synthetic mouse input.
    if not wasUnblocked and windowFocused and CONFIG.mouseShield then
        task.wait(.07)
    end
end
local function endAutoMouseInput()
    if mouseShieldSuspend<=0 then mouseShieldSuspend=0; return end
    -- Allow mouse-up dispatch to finish before restoring the intercepting GUI.
    if mouseShieldSuspend==1 and windowFocused and CONFIG.mouseShield then
        task.wait(.09)
    end
    mouseShieldSuspend=math.max(0,mouseShieldSuspend-1)
    updateMouseShield()
end
-- Keep input move + click in the SAME implementation. Do not mix VIM cursor
-- and native executor click (they may target different screen coordinates).
local function tapRawWithMethod(x,y,method)
    x,y=math.floor(x+.5),math.floor(y+.5)
    local viewport=liveViewport()
    if x<0 or y<0 or x>viewport.X or y>viewport.Y then
        return false,"outside Roblox viewport: "..x..","..y
    end
    if CONFIG.backgroundMode and not windowFocused then
        if not VIM then return false,"BACKGROUND cannot click: VIM unavailable" end
        method="VIM" -- never move/click an unrelated app window
    end
    if method=="TOUCH" then
        if not VIM then return false,"VirtualInputManager missing" end
        -- Simulate a true mobile touch rather than a desktop mouse event.
        -- Roblox TouchState: Begin=0, End=2. Always send End after Begin.
        local down,downErr=pcall(function() VIM:SendTouchEvent(1,0,x,y) end)
        if not down then return false,"TOUCH begin rejected: "..tostring(downErr) end
        delayCheck(.14)
        local up,upErr=pcall(function() VIM:SendTouchEvent(1,2,x,y) end)
        if not up then return false,"TOUCH end rejected: "..tostring(upErr) end
        return true,"TOUCH"
    end
    if method=="VIM" then
        if not VIM then return false,"VirtualInputManager missing" end
        local moved,mErr=pcall(function() VIM:SendMouseMoveEvent(x,y,game) end)
        if not moved then return false,"VIM move: "..tostring(mErr) end
        if not delayCheck(.08) then return false,"stopped" end
        -- Re-aim directly before click in case user touched the physical mouse.
        pcall(function() VIM:SendMouseMoveEvent(x,y,game) end)
        local down,dErr=pcall(function() VIM:SendMouseButtonEvent(x,y,0,true,game,0) end)
        if not down then return false,"VIM mouse down: "..tostring(dErr) end
        delayCheck(.12)
        local up,uErr=pcall(function() VIM:SendMouseButtonEvent(x,y,0,false,game,0) end)
        if not up then return false,"VIM mouse up: "..tostring(uErr) end
        return true,"VIM"
    end
    if method=="EXECUTOR" then
        if not windowFocused then return false,"Roblox unfocused: OS mouse disabled" end
        if type(mousemoveabs)~="function" then return false,"mousemoveabs unavailable" end
        local moved,mErr=pcall(mousemoveabs,x,y)
        if not moved then return false,"executor move: "..tostring(mErr) end
        if not delayCheck(.24) then return false,"stopped" end
        if type(mouse1press)=="function" and type(mouse1release)=="function" then
            local down,dErr=pcall(mouse1press)
            if not down then return false,"executor mouse1press: "..tostring(dErr) end
            delayCheck(.12)
            local up,uErr=pcall(mouse1release)
            if not up then return false,"executor mouse1release: "..tostring(uErr) end
            return true,"EXECUTOR press/release"
        elseif type(mouse1click)=="function" then
            local clicked,cErr=pcall(mouse1click)
            return clicked,clicked and "EXECUTOR click" or tostring(cErr)
        end
        return false,"executor mouse1click/press/release unavailable"
    end
    return false,"unknown mouse method "..tostring(method)
end
local function tapWithMethod(x,y,method)
    beginAutoMouseInput()
    local completed,ok,why=pcall(tapRawWithMethod,x,y,method)
    endAutoMouseInput()
    if not completed then return false,"input error: "..tostring(ok) end
    return ok,why
end
local function tap(x,y)
    local ok,why=tapWithMethod(x,y,preferredClickMode)
    if ok then return true,why end
    if CONFIG.backgroundMode and not windowFocused then
        return false,"VIM BACKGROUND input failed: "..tostring(why)
    end
    local other=preferredClickMode=="VIM" and "EXECUTOR" or "VIM"
    if MOBILE_449 and VIM and other=="EXECUTOR" then
        return false,"Android VIM click failed: "..tostring(why)
    end
    local fallback,result=tapWithMethod(x,y,other)
    if fallback then
        log("INPUT FALLBACK "..other.." after "..tostring(why))
        preferredClickMode=other
        return true,result
    end
    return false,"primary "..tostring(why).."; fallback "..tostring(result)
end
local function scale(x,y)
    local v=liveViewport()
    local rw,rh=data.viewport[1],data.viewport[2]
    -- Roblox's camera FOV is vertical. Preserve recording's vertical scale,
    -- then add the width difference equally on both sides (20:9 landscape).
    local ratio=v.Y/rh
    local mx=(v.X-rw*ratio)*0.5
    return math.floor(mx+x*ratio+0.5),math.floor(y*ratio+0.5)
end
-- Recorded mouse click at t=0.811s (1036,88) is the top-center Auto Skip
-- toggle. We intentionally replay ONLY this UI click; gameplay clicks stay filtered.
-- Read its actual red/green indicator first so a second run never turns it OFF.
local function autoSkipColorState(c)
    if not c then return nil end
    local r,g,b=c.R,c.G,c.B
    if g>.46 and g>r*1.48 and g>b*1.4 then return "GREEN" end
    if r>.50 and r>g*1.5 and r>b*1.32 then return "RED" end
    return nil
end
-- Auto Skip may have duplicate TextLabels under panels that are technically
-- Visible=true while their coordinates are ABOVE THE SCREEN.  A recent log
-- showed AutoSkipText at (384,-13), and the real OnAndOff button was missed.
-- Never send a mouse click to such a stale/offscreen label.
local function autoSkipOnScreen(n)
    if not n or not n:IsA("GuiObject") or not vis(n) then return false end
    local camera=workspace.CurrentCamera
    local vp=camera and camera.ViewportSize or Vector2.new(1920,1080)
    if vp.X<100 or vp.Y<100 then return false end
    local p=n.AbsolutePosition
    local sz=n.AbsoluteSize
    if sz.X<9 or sz.Y<9 then return false end
    local mid=midpoint(n)
    return mid.X>4 and mid.Y>4 and mid.X<vp.X-4 and mid.Y<vp.Y-4
end
local function autoSkipColorOf(n)
    if not n then return nil end
    local color=nil
    if n.BackgroundTransparency<.85 then
        color=autoSkipColorState(n.BackgroundColor3)
    end
    if not color and (n:IsA("ImageButton") or n:IsA("ImageLabel"))
        and n.ImageTransparency<.85 then
        color=autoSkipColorState(n.ImageColor3)
    end
    -- Some versions color a child Frame instead of the button itself.
    if not color then
        for _,c in ipairs(n:GetChildren()) do
            if c:IsA("GuiObject") and vis(c) and c.BackgroundTransparency<.85 then
                color=autoSkipColorState(c.BackgroundColor3)
                if color then break end
            end
        end
    end
    return color
end
local function locateAutoSkip()
    local camera=workspace.CurrentCamera
    local vp=camera and camera.ViewportSize or Vector2.new(1920,1080)
    local labels={}
    local buttons={}
    -- GUI absolute positions are already in the client's current viewport;
    -- do NOT scale them from the 1920x1080 recording or use stale coordinates.
    for _,n in ipairs(pg:GetDescendants()) do
        if autoSkipOnScreen(n) and (not gui or not n:IsDescendantOf(gui)) then
            local p=midpoint(n)
            if p.Y<vp.Y*.23 then
                if (n:IsA("TextLabel") or n:IsA("TextButton"))
                    and norm(txt(n))=="autoskip" then
                    labels[#labels+1]=n
                end
                -- Unlike label-based proximity search, find OnAndOff by
                -- its exact name FIRST.  This name was confirmed in a
                -- successful log of this game's own GUI.
                if n:IsA("GuiButton") and norm(n.Name)=="onandoff"
                    and n.AbsoluteSize.X<=110 and n.AbsoluteSize.Y<=110 then
                    buttons[#buttons+1]=n
                end
            end
        end
    end
    local bestLabel=nil
    local labelScore=math.huge
    for _,label in ipairs(labels) do
        local p=midpoint(label)
        -- Prefer the top-center HUD label, not a side-panel clone.
        local score=math.abs(p.X-vp.X*.57)+p.Y*.4
        if score<labelScore then bestLabel,labelScore=label,score end
    end
    local bestIndicator=nil
    local bestScore=math.huge
    for _,button in ipairs(buttons) do
        local p=midpoint(button)
        local score=math.abs(p.X-vp.X*.63)+p.Y*.25
        if bestLabel then
            local lab=midpoint(bestLabel)
            local near=(p.X>=lab.X+10 and p.X<=lab.X+210
                and math.abs(p.Y-lab.Y)<=70)
            if near then
                score=score-1000+math.abs(p.X-lab.X-85)*.6
            end
        end
        if score<bestScore then bestIndicator,bestScore=button,score end
    end
    -- Fallback: when the game uses an unhelpful name for the colored square,
    -- find only visible red/green controls to the RIGHT of the valid label.
    if not bestIndicator and bestLabel then
        local mid=midpoint(bestLabel)
        local right=bestLabel.AbsolutePosition.X+bestLabel.AbsoluteSize.X
        for _,n in ipairs(pg:GetDescendants()) do
            if autoSkipOnScreen(n) and n~=bestLabel
                and (not gui or not n:IsDescendantOf(gui)) then
                local p=midpoint(n)
                local sz=n.AbsoluteSize
                if sz.X>=12 and sz.Y>=12 and sz.X<=96 and sz.Y<=96
                    and p.X>mid.X+12 and p.X<right+140
                    and math.abs(p.Y-mid.Y)<50
                    and autoSkipColorOf(n) then
                    local score=math.abs(p.X-right-17)+2*math.abs(p.Y-mid.Y)
                    if score<bestScore then bestIndicator,bestScore=n,score end
                end
            end
        end
    end
    -- In small Roblox windows the top HUD may be shifted ABOVE the viewport.
    -- firesignal can activate a genuine OnAndOff GuiButton even while offscreen;
    -- clicking such negative coordinates with the physical mouse is unsafe.
    if not bestIndicator then
        local allLabels={}
        for _,n in ipairs(pg:GetDescendants()) do
            if (n:IsA("TextLabel") or n:IsA("TextButton")) and vis(n)
                and norm(txt(n))=="autoskip"
                and (not gui or not n:IsDescendantOf(gui)) then
                allLabels[#allLabels+1]=n
            end
        end
        local offscreenScore=math.huge
        for _,n in ipairs(pg:GetDescendants()) do
            if n:IsA("GuiButton") and vis(n)
                and norm(n.Name)=="onandoff"
                and n.AbsoluteSize.X>=9 and n.AbsoluteSize.X<=110
                and n.AbsoluteSize.Y>=9 and n.AbsoluteSize.Y<=110
                and (not gui or not n:IsDescendantOf(gui)) then
                local pos=midpoint(n)
                for _,label in ipairs(allLabels) do
                    local lp=midpoint(label)
                    local dx=pos.X-lp.X
                    local dy=math.abs(pos.Y-lp.Y)
                    if dx>=5 and dx<=230 and dy<=85 then
                        local score=math.abs(dx-85)+dy*2
                        if score<offscreenScore then
                            bestIndicator,bestLabel,offscreenScore=n,label,score
                        end
                    end
                end
            end
        end
    end
    return bestLabel,bestIndicator,autoSkipColorOf(bestIndicator)
end
-- Prefer the actual OnAndOff GuiButton over large labels/overlays.
local function autoSkipButtons(label,indicator)
    local out={}
    local seen={}
    local function add(n,score)
        if not n or seen[n] or not n:IsA("GuiButton") then return end
        -- Offscreen exact-name OnAndOff is eligible for GUI signals ONLY.
        if not autoSkipOnScreen(n) and not
            (norm(n.Name)=="onandoff" and vis(n)) then return end
        seen[n]=true
        out[#out+1]={node=n,score=score}
    end
    if indicator then
        if indicator:IsA("GuiButton") then add(indicator,-1000) end
        local parent=indicator.Parent
        for i=1,3 do
            if not parent or parent==pg then break end
            add(parent,-200+i)
            parent=parent.Parent
        end
    end
    if label then
        add(label,-900)
        local parent=label.Parent
        for i=1,3 do
            if not parent or parent==pg then break end
            add(parent,-100+i)
            parent=parent.Parent
        end
    end
    -- Do not click broad input overlays: only a small GuiButton that
    -- overlaps the actual toggle can be a candidate.
    if indicator then
        local q=midpoint(indicator)
        for _,n in ipairs(pg:GetDescendants()) do
            if n:IsA("GuiButton") and autoSkipOnScreen(n)
                and (not gui or not n:IsDescendantOf(gui)) then
                local pos,sz=n.AbsolutePosition,n.AbsoluteSize
                if sz.X<=310 and sz.Y<=115 and sz.X>=9 and sz.Y>=9
                    and q.X>=pos.X and q.X<=pos.X+sz.X
                    and q.Y>=pos.Y and q.Y<=pos.Y+sz.Y then
                    add(n,-50+math.abs((midpoint(n)-q).Magnitude)*.03)
                end
            end
        end
    end
    table.sort(out,function(a,b) return a.score<b.score end)
    return out
end
local function autoSkipWaitGreen(seconds)
    local untilAt=os.clock()+seconds
    repeat
        if stopped then return false end
        local _,_,state=locateAutoSkip()
        if state=="GREEN" then return true end
        task.wait(.12)
    until os.clock()>=untilAt
    return false
end
local function autoSkipLogTarget(n)
    if not n then return "nil" end
    local pos=midpoint(n)
    return n.Name.." ["..n.ClassName.."] @"..math.floor(pos.X)..","..math.floor(pos.Y)
end
local function ensureAutoSkipGreen(recordedX,recordedY)
    local label,indicator,state
    -- Roblox HUD may initially be offscreen: inspect true named controls and
    -- wait for a readable red/green toggle before sending signals.
    for attempt=1,65 do
        if stopped then return false,"stopped" end
        label,indicator,state=locateAutoSkip()
        if indicator and state then break end
        if attempt==1 or attempt==20 or attempt==45 then
            log("AUTO SKIP WAIT VISIBLE TOGGLE | label="..tostring(label and autoSkipLogTarget(label) or "nil")
                .." | indicator="..tostring(indicator and autoSkipLogTarget(indicator) or "nil"))
        end
        task.wait(.18)
    end
    if not indicator or not state then
        return false,"No red/green Auto Skip OnAndOff found; never clicking offscreen label"
    end
    log("AUTO SKIP UI label="..autoSkipLogTarget(label)
        .." | indicator="..autoSkipLogTarget(indicator)
        .." | state="..tostring(state))
    if state=="GREEN" then
        log("AUTO SKIP GREEN confirmed (already on)")
        return true,"already GREEN"
    end
    -- Signal path is independent of cursor hitboxes and can operate on UI
    -- whose colored square is only a visual indicator.
    local buttons=autoSkipButtons(label,indicator)
    log("AUTO SKIP GUI candidates="..#buttons)
    for i=1,math.min(4,#buttons) do
        log("AUTO SKIP target #"..i..": "..autoSkipLogTarget(buttons[i].node))
    end
    if type(firesignal)=="function" then
        for i=1,math.min(3,#buttons) do
            local button=buttons[i].node
            for _,signalName in ipairs({"MouseButton1Click","Activated"}) do
                if stopped then return false,"stopped" end
                if autoSkipWaitGreen(.08) then
                    log("AUTO SKIP GREEN confirmed")
                    return true,"GUI already changed"
                end
                local ok,err=pcall(function()
                    if signalName=="Activated" then
                        firesignal(button.Activated,nil,1)
                    else
                        firesignal(button.MouseButton1Click)
                    end
                end)
                log("AUTO SKIP signal "..signalName.." on "..autoSkipLogTarget(button)
                    .." | "..(ok and "sent" or tostring(err)))
                if ok and autoSkipWaitGreen(.45) then
                    log("AUTO SKIP GREEN confirmed by GUI signal")
                    return true,"GUI "..signalName
                end
            end
        end
    else
        log("AUTO SKIP: firesignal not available; using mouse click hitboxes")
    end
    -- If signals were not attached, try the actual GUI hitbox, followed by
    -- the label and indicator. Re-read state BEFORE every click to avoid OFF.
    local targets={}
    local seen={}
    local function addTarget(n,kind)
        if not n or seen[n] or not autoSkipOnScreen(n) then return end
        seen[n]=true
        local q=midpoint(n)
        targets[#targets+1]={x=q.X,y=q.Y,kind=kind,n=n}
    end
    for i=1,math.min(3,#buttons) do addTarget(buttons[i].node,"BUTTON") end
    -- Only click the REAL on-screen button. A TextLabel is informational and
    -- may be offscreen or not clickable. Never fall back to old 1920x1080 coords.
    addTarget(indicator,"COLOR")
    if #targets==0 then
        return false,"Auto Skip not GREEN and toggle is offscreen; mouse fallback disabled"
    end
    for i=1,math.min(5,#targets) do
        if stopped then return false,"stopped" end
        local _,_,before=locateAutoSkip()
        if before=="GREEN" then
            log("AUTO SKIP GREEN confirmed")
            return true,"GREEN before click"
        end
        local q=targets[i]
        local mode=(i==5) and "EXECUTOR" or "VIM"
        local ok,why=tapWithMethod(q.x,q.y,mode)
        log("AUTO SKIP "..q.kind.." CLICK #"..i.." via "..mode
            .." @"..math.floor(q.x)..","..math.floor(q.y)
            .." | "..tostring(why))
        if ok and autoSkipWaitGreen(.55) then
            log("AUTO SKIP GREEN confirmed by "..q.kind.." click")
            return true,"click "..q.kind
        end
    end
    local _,_,after=locateAutoSkip()
    return false,"Auto Skip still "..tostring(after).."; GUI paths logged for diagnosis"
end
local function project(pos)
    local c=workspace.CurrentCamera
    if not c then return nil end
    local p,inView=c:WorldToViewportPoint(pos)
    local v=c.ViewportSize
    if not inView or p.X<60 or p.X>v.X-60 or p.Y<60 or p.Y>v.Y-60 then return nil end
    return math.floor(p.X+.5),math.floor(p.Y+.5)
end
local function freeze(t)
    cameraFrozen=t
    cameraOverride=nil
    setCamera(t)
    task.wait(.07)
end
local function claimedModel(m)
    for _,known in pairs(placedModels) do
        if known==m then return true end
    end
    return false
end
local function matchingAtRecordedSpot(info,baseline)
    local want=Vector3.new(info.pos[1],info.pos[2],info.pos[3])
    local near={}
    for _,model in ipairs(modelsFor(info.unit)) do
        if not claimedModel(model) and (not baseline or not baseline[model]) then
            local p=modelPos(model)
            if p and worldXZ(p,want)<=CONFIG.placementRadiusXZ then
                near[#near+1]=model
            end
        end
    end
    if #near==1 then return near[1] end
    if #near>1 then return nil,"multiple unclaimed units at same recorded point" end
end
-- SAFETY v0.8.14: the old script looked ONLY for a new model within 2
-- studs. At Chef TV #9 its log showed existing chef_tv_man 2 -> 3 during
-- overhead recovery, yet it kept sending clicks. Detect *every* new troop,
-- including the wrong unit or a correct unit far from the intended point.
-- One spawned model must end further placement clicks immediately.
local function freshPlacedTroop(beforeAll,expectedUnit,goal)
    local fresh={}
    for _,kind in ipairs({"pumpkin_farmer","chef_tv_man","medic_cameraman"}) do
        for _,m in ipairs(modelsFor(kind)) do
            if not beforeAll[m] and not claimedModel(m) then
                fresh[#fresh+1]={kind=kind,model=m,pos=modelPos(m)}
            end
        end
    end
    if #fresh==0 then return nil,nil,nil end
    if #fresh>1 then
        local names={}
        for i=1,math.min(#fresh,4) do
            names[#names+1]=fresh[i].kind
        end
        return nil,"UNSAFE: "..#fresh.." NEW troops detected ("..table.concat(names,",")
            .."); STOPPED so no extra units are placed",nil
    end
    local spawned=fresh[1]
    if spawned.kind~=expectedUnit then
        return nil,"WRONG UNIT SPAWNED: expected "..expectedUnit
            .." but got "..spawned.kind.."; STOPPED to avoid duplicates",nil
    end
    if not spawned.pos then
        return nil,"NEW "..expectedUnit.." exists but pivot not ready; STOPPED to avoid duplicate clicks",nil
    end
    local distance=worldXZ(spawned.pos,goal)
    if distance>CONFIG.placementNearbyAcceptXZ then
        return nil,string.format(
            "WRONG POSITION: a new %s spawned at X=%.2f Z=%.2f, %.2f studs from target X=%.2f Z=%.2f; STOPPED WITHOUT ANOTHER CLICK",
            expectedUnit,spawned.pos.X,spawned.pos.Z,distance,goal.X,goal.Z),distance
    end
    return spawned.model,nil,distance
end

-- On a background window the executor/VIM may report that a numeric key was
-- sent while the in-game placement preview was silently lost.  Reassert selection
-- by switching to a DIFFERENT slot and back.  A same-slot key alone can toggle
-- the preview OFF.  Never count a placement until a new model is observed.
local function mobileHotbarReport()
    if not MOBILE_449 then return end
    local panel=pg:FindFirstChild("TroopsSelector",true)
    if not panel then
        log("MOBILE HOTBAR DIAG | TroopsSelector absent; VIM number keys might not select a troop")
        return
    end
    local entries={}
    for _,v in ipairs(panel:GetDescendants()) do
        if v:IsA("GuiButton") then
            local text=v:IsA("TextButton") and v.Text or ""
            entries[#entries+1]=v.Name.."="..text
            if #entries>=12 then break end
        end
    end
    log("MOBILE HOTBAR DIAG | "..panel:GetFullName().." | buttons="..table.concat(entries,"; "))
end
local function restorePlacementPreview(unit,id)
    local target=slots[unit]
    local alternate=(target=="One") and "Two" or "One"
    local keepRotations=math.min(rotationsSinceSelection,8)
    log("PREVIEW RECOVERY #"..id.." | switch "..alternate.." -> "..target
        .." | R rotations="..keepRotations.." | focus="..tostring(windowFocused))
    local function pulse(key)
        local ok,method=sendKey(key,true)
        if not ok then return false,method end
        if not delayCheck(.095) then return false,"stopped" end
        local released,why=sendKey(key,false)
        if not released then return false,why end
        if not delayCheck(.20) then return false,"stopped" end
        return true,method
    end
    local ok,why=pulse(alternate)
    if not ok then return false,"alternate slot: "..tostring(why) end
    ok,why=pulse(target)
    if not ok then return false,"target slot: "..tostring(why) end
    selectedPreview=unit
    -- Re-apply the R presses that the recorded run used for this preview.
    for _=1,keepRotations do
        ok,why=pulse("R")
        if not ok then return false,"rotation restore: "..tostring(why) end
    end
    log("PREVIEW RECOVERY #"..id.." | input sequence completed (not yet verified)")
    return true
end

local function cameraForPlacement(info,recT)
    cameraFrozen=recT
    -- The recording stores the exact CFrame used to project this world point.
    -- Applying it is more reliable than camera interpolation at sped-up times.
    cameraOverride=cframeFrom(info.cam)
    setCamera(recT,cameraOverride)
    task.wait(.14)
end
-- Final recovery: change only the CAMERA viewpoint (never the avatar) so the
-- screen-to-world placement ray can hit an unobstructed patch of ground.  The
-- strategy still requires a new model within 2 studs of the ORIGINAL point.
local function alternatePlacementCamera(info,recT,variant)
    local ground=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    local offsets={
        Vector3.new(0,30,8),
        Vector3.new(12,29,-6),
        Vector3.new(-11,31,-8),
        Vector3.new(6,34,12),
    }
    local offset=offsets[((variant-1)%#offsets)+1]
    local cf=CFrame.lookAt(ground+offset,ground)
    cameraFrozen=recT
    cameraOverride=cf
    setCamera(recT,cf)
    task.wait(.22)
    local x,y=project(ground)
    if not x then return nil,nil,"ground out of view from overhead camera" end
    return x,y,nil
end

-- v0.8.17: If the exact click is repeatedly rejected, first examine
-- a few candidate points CLOSE TO the recorded position. Existing towers can
-- overlap a new tower's placement footprint even when the camera ray hits ground.
-- Only visible, grounded, unoccupied candidates within the strict offset cap
-- may be clicked. This does not bypass game placement rules.
local function nearbySafePlacementPoints(info,goal)
    local folder=workspace:FindFirstChild("Troops")
    local existing={}
    if folder then
        for _,m in ipairs(folder:GetChildren()) do
            if m:IsA("Model") then
                local pos=modelPos(m)
                if pos then existing[#existing+1]=pos end
            end
        end
    end
    local rayParams=RaycastParams.new()
    rayParams.FilterType=Enum.RaycastFilterType.Exclude
    local excludes={}
    if folder then excludes[#excludes+1]=folder end
    if player.Character then excludes[#excludes+1]=player.Character end
    rayParams.FilterDescendantsInstances=excludes
    local candidates={}
    local radii={2.20,2.80,3.40}
    for _,radius in ipairs(radii) do
        for n=0,11 do
            local theta=n*math.pi/6
            local proposed=Vector3.new(goal.X+math.cos(theta)*radius,
                info.ground[2],goal.Z+math.sin(theta)*radius)
            local ok,hit=pcall(function()
                return workspace:Raycast(proposed+Vector3.new(0,70,0),Vector3.new(0,-145,0),rayParams)
            end)
            if ok and hit and math.abs(hit.Position.Y-info.ground[2])<1.65 then
                local point=hit.Position
                local drift=worldXZ(point,goal)
                if drift<=CONFIG.adaptiveMaxOffset then
                    local minSeparation=1000
                    for _,other in ipairs(existing) do
                        minSeparation=math.min(minSeparation,worldXZ(other,point))
                    end
                    if minSeparation>=CONFIG.adaptiveMinSeparation then
                        -- Prefer a clear point, but discourage large deviations.
                        candidates[#candidates+1]={pos=point,score=math.min(minSeparation,12)-drift*.38,
                            drift=drift,clearance=minSeparation}
                    end
                end
            end
        end
    end
    table.sort(candidates,function(a,b)
        return a.score>b.score
    end)
    local choices={}
    for _,item in ipairs(candidates) do
        local different=true
        for _,chosen in ipairs(choices) do
            if worldXZ(chosen.pos,item.pos)<1.1 then different=false; break end
        end
        if different then choices[#choices+1]=item end
        if #choices>=3 then break end
    end
    return choices
end

local function aimAtNearbyPlacement(info,recT,candidate)
    local origin=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    -- High angled view shows a ground patch without moving the avatar.
    local cf=CFrame.lookAt(origin+Vector3.new(1,38,12),origin)
    cameraFrozen=recT
    cameraOverride=cf
    setCamera(recT,cf)
    task.wait(.20)
    local x,y=project(candidate.pos)
    if not x then return nil,nil,"candidate outside viewport" end
    local camera=workspace.CurrentCamera
    local ray=camera:ViewportPointToRay(x,y)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignored={}
    local troops=workspace:FindFirstChild("Troops")
    if troops then ignored[#ignored+1]=troops end
    if player.Character then ignored[#ignored+1]=player.Character end
    params.FilterDescendantsInstances=ignored
    local ok,hit=pcall(function() return workspace:Raycast(ray.Origin,ray.Direction*300,params) end)
    if not ok or not hit or worldXZ(hit.Position,candidate.pos)>1.15 then
        return nil,nil,"camera ray not on candidate ground"
    end
    return x,y,nil
end

local function placementRayInfo(x,y,goal)
    local camera=workspace.CurrentCamera
    if not camera then return "no-camera" end
    local ray=camera:ViewportPointToRay(x,y)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignored={}
    local troops=workspace:FindFirstChild("Troops")
    if troops then ignored[#ignored+1]=troops end
    if player.Character then ignored[#ignored+1]=player.Character end
    params.FilterDescendantsInstances=ignored
    local ok,result=pcall(function()
        return workspace:Raycast(ray.Origin,ray.Direction*700,params)
    end)
    if not ok then return "raycast-error:"..tostring(result) end
    if not result then return "no-surface-hit" end
    local p=result.Position
    return tostring(result.Instance and result.Instance.Name or "?")
        .."; ray-to-goal="..string.format("%.1f",worldXZ(p,goal)).." studs"
end

-- v0.8.17 WORLD-TARGET PICKER: the demonstration video places troops while
-- barely moving the camera. The actual server commands are not visible in that
-- video, so do NOT guess any remote names or fire unverified server events.
-- Instead, validate where a proposed mouse click really intersects the ground.
-- Only adjust a previously failed recorded click; keep the first original click.
local function rayTargetScore(x,y,ground)
    local camera=workspace.CurrentCamera
    if not camera then return nil end
    local viewport=camera.ViewportSize
    if x<32 or y<32 or x>viewport.X-32 or y>viewport.Y-32 then return nil end
    local ray=camera:ViewportPointToRay(x,y)
    local params=RaycastParams.new()
    params.FilterType=Enum.RaycastFilterType.Exclude
    local ignores={}
    local troops=workspace:FindFirstChild("Troops")
    if troops then ignores[#ignores+1]=troops end
    if player.Character then ignores[#ignores+1]=player.Character end
    params.FilterDescendantsInstances=ignores
    local ok,hit=pcall(function()
        return workspace:Raycast(ray.Origin,ray.Direction*700,params)
    end)
    if not ok or not hit then return nil end
    -- Walls and roofs must never be substituted for playable ground.
    if hit.Normal.Y<.70 or math.abs(hit.Position.Y-ground.Y)>2.1 then return nil end
    return worldXZ(hit.Position,ground)
end

local function correctedGroundClick(info,originalX,originalY)
    local ground=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    local px,py=project(ground)
    local choices={{originalX,originalY}}
    if px and py then choices[#choices+1]={px,py} end
    -- In the recorded run a tower sometimes appeared when clicking a few pixels
    -- away from the center; test a small local lattice, never a remote random spot.
    for _,off in ipairs({{5,0},{-5,0},{0,5},{0,-5},{5,5},{-5,5},{5,-5},{-5,-5},
        {9,0},{-9,0},{0,9},{0,-9}}) do
        choices[#choices+1]={originalX+off[1],originalY+off[2]}
    end
    local base=rayTargetScore(originalX,originalY,ground)
    local bestX,bestY,bestError=nil,nil,math.huge
    for _,q in ipairs(choices) do
        local errorValue=rayTargetScore(q[1],q[2],ground)
        if errorValue and errorValue<=CONFIG.worldRayMaxDrift then
            -- Prefer minimal world error, then a click close to the genuine recording.
            local score=errorValue+math.abs(q[1]-originalX)*.003
                +math.abs(q[2]-originalY)*.003
            if score<bestError then
                bestError=score
                bestX,bestY=q[1],q[2]
            end
        end
    end
    if not bestX then return nil,nil,base,"no clear ground ray close to recorded placement" end
    return bestX,bestY,base,bestError
end

-- ===== PER-SESSION BRIDGENET2 CALIBRATION =====
-- The same successful place had opcode W in an earlier client and j in this
-- client's context capture. BridgeNet2 generates compact ids; NEVER save them
-- to disk or assume j is correct for the next server.
-- Capture the ACTUAL outbound placement arguments, not just the first Pumpkin code.
-- The first troop of EACH type is placed natively so we learn its exact payload.
local sessionPlaceCode=nil
local sessionPlaceCaptured=0
local sessionHookReady=false
local sessionHookError=nil
local sessionPlaceProfiles={}
local observedPlaceCalls={}
local calibrationRotationPending=0
local gameRemote=game:GetService("ReplicatedStorage"):FindFirstChild("dataRemoteEvent")
if type(hookmetamethod)=="function" and type(getnamecallmethod)=="function" then
    local oldNamecall
    local function onNamecall(self,...)
        if getnamecallmethod()=="FireServer" and typeof(self)=="Instance"
            and self.Name=="dataRemoteEvent" then
            local gameOrigin=true
            if type(checkcaller)=="function" then
                local ok,ours=pcall(checkcaller)
                if ok and ours then gameOrigin=false end
            end
            if gameOrigin then
                local payload=select(1,...)
                if typeof(payload)=="table" and typeof(payload[1])=="table"
                    and typeof(payload[1][1])=="string"
                    and typeof(payload[1][2])=="Vector3"
                    and typeof(payload[1][3])=="number"
                    and typeof(payload[2])=="string" then
                    sessionPlaceCaptured=sessionPlaceCaptured+1
                    observedPlaceCalls[#observedPlaceCalls+1]={
                        at=os.clock(), name=payload[1][1], pos=payload[1][2],
                        rotation=payload[1][3], code=payload[2]
                    }
                    if #observedPlaceCalls>40 then table.remove(observedPlaceCalls,1) end
                end
            end
        end
        return oldNamecall(self,...)
    end
    local fn=(type(newcclosure)=="function" and newcclosure(onNamecall)) or onNamecall
    local ok,previous=pcall(function() return hookmetamethod(game,"__namecall",fn) end)
    if ok and type(previous)=="function" then
        oldNamecall=previous
        sessionHookReady=true
    else
        sessionHookError="namecall hook failed: "..tostring(previous)
    end
else
    sessionHookError="hookmetamethod/getnamecallmethod unavailable in Volt"
end
local function calibrationStatus()
    return "observed calls="..tostring(sessionPlaceCaptured)
        .." hook="..tostring(sessionHookReady)
end
local function findObservedPlaceSince(startIndex,spawn)
    local pos=modelPos(spawn)
    if not pos then return nil end
    local nearest,best=nil,math.huge
    for i=startIndex+1,#observedPlaceCalls do
        local entry=observedPlaceCalls[i]
        local dx=entry.pos.X-pos.X
        local dz=entry.pos.Z-pos.Z
        local distance=math.sqrt(dx*dx+dz*dz)
        if distance<best then nearest,best=entry,distance end
    end
    if best>5 then return nil end
    return nearest,best
end
local function placementErrorText()
    for _,element in ipairs(pg:GetDescendants()) do
        if element:IsA("TextLabel") and vis(element) then
            local t=tostring(element.Text or "")
            if t:find("Error 002",1,true) or t:find("Error 00",1,true) then
                return t:sub(1,170)
            end
        end
    end
    return nil
end
local function directRemote()
    local rs=game:GetService("ReplicatedStorage")
    local remote=rs:FindFirstChild("dataRemoteEvent")
    if remote and remote:IsA("RemoteEvent") then return remote end
    return nil,"ReplicatedStorage.dataRemoteEvent (RemoteEvent) missing"
end
local function doCalibrationPlacement(id,recT)
    collapseReplayMenu(true)
    local info=data.places[tostring(id)]
    if not info then return false,"unknown placement id "..tostring(id) end
    if not workspace:FindFirstChild("Troops") then
        return false,"Workspace.Troops missing; start inside the match"
    end
    local goal=Vector3.new(info.pos[1],info.pos[2],info.pos[3])
    local ground=Vector3.new(info.ground[1],info.ground[2],info.ground[3])
    local baseline={}
    for _,m in ipairs(modelsFor(info.unit)) do baseline[m]=true end
    local baselineAll={}
    -- Include all recognized and other Models: a new model must not trigger
    -- repeated clicks just because its type or pivot differs from recording.
    local troopFolder=workspace:FindFirstChild("Troops")
    if troopFolder then
        for _,m in ipairs(troopFolder:GetChildren()) do
            if m:IsA("Model") then baselineAll[m]=true end
        end
    end
    local function confirmedPlacement(model,mode,x,y,dist)
        placedModels[id]=model
        placedTimes[id]=os.clock()
        selectedPreview=nil
        rotationsSinceSelection=0
        if mode=="EXECUTOR" or mode=="VIM" or mode=="TOUCH" then preferredClickMode=mode end
        cameraFrozen=nil; cameraOverride=nil
        local difference=dist or (modelPos(model) and worldXZ(modelPos(model),goal)) or 0
        if difference>CONFIG.placementRadiusXZ then
            say("PLACED WITH OFFSET #"..id,info.unit
                .." | new model confirmed "..string.format("%.2f",difference).." studs away; NO MORE CLICKS")
        else
            say("PLACED CONFIRMED #"..id,info.unit.." via "..tostring(mode)
                ..(x and (" @"..x..","..y) or ""))
        end
        return true
    end
    -- In previous v0.8, replayed clicks could spawn before the p event.
    -- Only accept an unclaimed model within the recorded position tolerance.
    local preexisting,preWhy=matchingAtRecordedSpot(info,nil)
    if preexisting then
        placedModels[id]=preexisting
        placedTimes[id]=os.clock()
        selectedPreview=nil
        rotationsSinceSelection=0
        say("PLACED #"..id.." detected already",info.unit)
        cameraFrozen=nil; cameraOverride=nil
        return true
    end
    if preWhy then return false,preWhy end
    local attempts=0
    local adaptivePoints=nil
    local lastCashLog=0
    local failures={}
    while not stopped do
        -- Check every new model BEFORE accepting one near the target: this
        -- also catches a wrong-slot spawn or two simultaneous stray units.
        local fresh,freshIssue,freshDistance=freshPlacedTroop(baselineAll,info.unit,goal)
        if fresh then
            return confirmedPlacement(fresh,"SPAWN WATCH",nil,nil,freshDistance)
        end
        if freshIssue then
            log("PLACE SAFETY #"..id.." | "..freshIssue)
            return false,freshIssue
        end
        local found,issue=matchingAtRecordedSpot(info,baseline)
        if found then return confirmedPlacement(found,"EXACT SPOT",nil,nil,0) end
        if issue then return false,issue end
        local cost=CONFIG.placeCost[info.unit] or 0
        local cash=cashOnHud(nil)
        if CONFIG.placementWaitForCash and cash~=nil and cash<cost then
            if os.clock()-lastCashLog>4 then
                local _,_,skipState=locateAutoSkip()
                say("WAIT CASH PLACE #"..id,info.unit.." $"..cash.."/$"..cost.." | Auto Skip "..tostring(skipState))
                lastCashLog=os.clock()
            end
            delayCheck(.35)
        else
            local maxAttempts=MOBILE_449 and math.min(CONFIG.placementAttempts,4) or CONFIG.placementAttempts
            if attempts>=maxAttempts then
                if MOBILE_449 then
                    log("MOBILE 449dp DIAG | TOUCH and VIM tried without confirmed troop; check hotbar selection, placement range, and whether preview appears")
                end
                return false,"Placement #"..id.." not confirmed after "..attempts.." safe attempts; no repeat overhead spam. "..table.concat(failures," | ")
            end
            attempts=attempts+1
            beginAutoMouseInput()
            -- First two attempts use the exact recorded preview/click.  If both
            -- failed, rebuild preview selection independently of our bookkeeping.
            if attempts==3 or attempts==5 or attempts==7 then
                if attempts==3 then mobileHotbarReport() end
                local okPreview,whyPreview=restorePlacementPreview(info.unit,id)
                if not okPreview then
                    log("PREVIEW RECOVERY FAILED #"..id..": "..tostring(whyPreview))
                    endAutoMouseInput()
                    return false,"cannot restore preview: "..tostring(whyPreview)
                end
            end
            -- Keep shield suspended during the entire placement interaction.
            -- When it was only suspended around a click, GUI input often hit
            -- CatchAccidentalClicks instead of the actual map.
            cameraForPlacement(info,recT)
            -- Recorded number keys select the preview BEFORE R rotations. v0.8
            -- selected the SAME slot again here, toggling the preview OFF.
            if selectedPreview~=info.unit then
                say("SELECT HOTBAR #"..id,info.unit)
                local okKey,method=sendKey(slots[info.unit],true)
                if not okKey then endAutoMouseInput(); return false,"cannot select slot: "..tostring(method) end
                delayCheck(.10)
                sendKey(slots[info.unit],false)
                selectedPreview=info.unit
                rotationsSinceSelection=0
                delayCheck(.32)
            end
            -- First native placement of each troop type: restore the recorded
            -- R rotation before the actual click. A previously skipped R event
            -- must not change the orientation of the server-calibration sample.
            if calibrationRotationPending>0 then
                local count=calibrationRotationPending
                for _=1,count do
                    local rDown,rErr=sendKey("R",true)
                    if not rDown then
                        endAutoMouseInput()
                        return false,"calibration R key down failed: "..tostring(rErr)
                    end
                    delayCheck(.085)
                    sendKey("R",false)
                    delayCheck(.10)
                    rotationsSinceSelection=rotationsSinceSelection+1
                end
                say("CALIBRATION ROTATION #"..id,"applied "..count.." R presses")
                calibrationRotationPending=0
            end
            -- On retries keep preview selected; sending the numeric key again
            -- can cancel it. Try both complete input pipelines instead.
            -- The original v0.8.3 successfully placed #1 at (947,483), i.e.
            -- the exact mouse click from the recording. Versions after adding
            -- Mouse Shield used ground projection (948,455), 28 px too high.
            -- Prioritize the genuine recorded mouse coordinates. Screen sizes
            -- are scaled by the original recording viewport.
            local savedX,savedY=scale(info.click[1],info.click[2])
            local projX,projY=project(ground)
            local x,y=savedX,savedY
            -- If the first touch is ignored, retry once with VIM mouse input;
            -- do not use Windows-only executor APIs on an Android device.
            local method=(MOBILE_449 and VIM)
                and ((attempts%2==1) and "TOUCH" or "VIM")
                or ((attempts%2==1) and "VIM" or "EXECUTOR")
            -- Unfocused Roblox cannot safely receive executor (OS) mouse input:
            -- tapRawWithMethod redirects EXECUTOR -> VIM in the background.
            -- Log the EFFECTIVE method to avoid misleading diagnostics.
            if CONFIG.backgroundMode and not windowFocused then method="VIM" end
            -- Only after the original click fails with BOTH methods, try an
            -- explicitly diagnosed alternative projection; don't guess clicks.
            if attempts==4 and projX and projY then
                x,y=projX,projY
            end
            -- On later attempts use a small screen-space adjustment around
            -- the genuine recorded click.  The world-position verification
            -- still requires the intended unit within 2 studs (no false success).
            if attempts==6 then x,y=savedX-8,savedY+6 end
            if attempts==7 then x,y=savedX+8,savedY-6 end
            -- Only when the recorded point and small pixel corrections all
            -- failed, search a few grounded NEARBY candidates. Never click
            -- farther than 3.55 studs from the recorded target.
            if attempts>=8 and CONFIG.adaptivePlacement then
                if not adaptivePoints then
                    adaptivePoints=nearbySafePlacementPoints(info,goal)
                    log("ADAPTIVE SEARCH #"..id.." | candidates="..#adaptivePoints
                        .." | maxOffset="..CONFIG.adaptiveMaxOffset.." studs")
                end
                local choice=adaptivePoints[attempts-7]
                if not choice then
                    endAutoMouseInput()
                    return false,"No additional safe ground within "..CONFIG.adaptiveMaxOffset
                        .." studs of placement #"..id.."; refusing random clicks"
                end
                -- Before trying a new point rebuild preview once, not after
                -- every click. A valid preview is essential for unit placement.
                if attempts==8 then
                    local okPreview,whyPreview=restorePlacementPreview(info.unit,id)
                    if not okPreview then
                        endAutoMouseInput()
                        return false,"Adaptive preview recovery failed: "..tostring(whyPreview)
                    end
                end
                local ax,ay,reason=aimAtNearbyPlacement(info,recT,choice)
                if not ax then
                    endAutoMouseInput()
                    return false,"Adaptive camera failed: "..tostring(reason)
                end
                x,y=ax,ay
                log(string.format("ADAPTIVE TARGET #%d | drift=%.2f studs | nearestOther=%.2f | x=%.2f z=%.2f | click=%d,%d",
                    id,choice.drift,choice.clearance,choice.pos.X,choice.pos.Z,x,y))
                log("ADAPTIVE RAY #"..id.." | "..placementRayInfo(x,y,choice.pos))
            end
            -- Use verified world ray as a recovery, not as a replacement for a
            -- proven first click. Keeping the first recorded click is critical
            -- for the initial farms and existing working positions.
            if CONFIG.worldRayCorrection and attempts>=3 and attempts<=7
                and (attempts==3 or attempts==5 or attempts==7) then
                local smartX,smartY,oldError,newError=correctedGroundClick(info,savedX,savedY)
                if smartX and type(newError)=="number" and
                    (not oldError or newError+0.12<oldError) then
                    x,y=smartX,smartY
                    log(string.format("WORLD TARGET #%d | click=%d,%d | ray-error=%.2f studs | old=%s",
                        id,x,y,newError,oldError and string.format("%.2f",oldError) or "none"))
                elseif attempts==3 then
                    log("WORLD TARGET #"..id.." | no safer correction; retaining recorded click")
                end
            end
            if attempts==1 then
                log("PLACE TARGET #"..id.." | RECORDED @"..savedX..","..savedY
                    .." | WORLD PROJECTED @"..tostring(projX)..","..tostring(projY)
                    .." | deltaY="..tostring(projY and (savedY-projY) or "n/a"))
            end
            -- While our automation clicks, the protective GUI MUST be disabled
            -- and inactive; this is also true during cursor movement.
            if mouseShieldGui then mouseShieldGui.Enabled=false end
            if mouseShieldSurface then mouseShieldSurface.Active=false; mouseShieldSurface.Visible=false end
            say("PLACE #"..id.." ATTEMPT "..attempts,info.unit.." / "..method.." @"..x..","..y)
            log("PLACE INPUT GUARD | shield="..tostring(mouseShieldGui and mouseShieldGui.Enabled)
                .." | suspended="..tostring(mouseShieldSuspend).." | focus="..tostring(windowFocused))
            local clickOk,clickWhy=tapWithMethod(x,y,method)
            endAutoMouseInput()
            if not clickOk then
                failures[#failures+1]=method..": "..tostring(clickWhy)
                log("PLACE INPUT FAILURE #"..id..": "..tostring(clickWhy))
                delayCheck(.18)
            else
                local untilAt=os.clock()+CONFIG.placementConfirmWait
                while not stopped and os.clock()<untilAt do
                    local justSpawned,spawnSafetyError,spawnDist=freshPlacedTroop(baselineAll,info.unit,goal)
                    if justSpawned then
                        return confirmedPlacement(justSpawned,method,x,y,spawnDist)
                    end
                    if spawnSafetyError then
                        log("PLACE SAFETY #"..id.." | "..spawnSafetyError)
                        return false,spawnSafetyError
                    end
                    local spawned,spawnIssue=matchingAtRecordedSpot(info,baseline)
                    if spawned then
                        return confirmedPlacement(spawned,method,x,y,0)
                    end
                    if spawnIssue then return false,spawnIssue end
                    delayCheck(.13)
                end
                failures[#failures+1]=method.." clicked but no matching model appeared"
                log("PLACE #"..id.." input sent, no model detected near ("..goal.X..", "..goal.Z..")")
                -- Placement can be rejected if the avatar is too far away even
                -- though a Scriptable camera can view the target. Log distance
                -- without silently moving the avatar against the user's wishes.
                local root=getRoot()
                local dist=root and worldXZ(root.Position,goal)
                local screenReasons={}
                for _,v in ipairs(pg:GetDescendants()) do
                    if v:IsA("TextLabel") and vis(v) then
                        -- screenVisible is defined later in this file; vis is enough here.
                        local text=norm(txt(v))
                        if text:find("limit",1,true) or text:find("toofar",1,true)
                            or text:find("cannotplace",1,true) or text:find("maxunits",1,true)
                            or text:find("closer",1,true) or text:find("notenough",1,true) then
                            screenReasons[#screenReasons+1]=txt(v):sub(1,55)
                            if #screenReasons>=3 then break end
                        end
                    end
                end
                log("PLACE DIAG #"..id.." | existing "..info.unit.."="..#modelsFor(info.unit)
                    .." | avatar distance="..(dist and string.format("%.1f",dist) or "unknown")
                    .." studs | UI hints="..(#screenReasons>0 and table.concat(screenReasons,"; ") or "none"))
            end
        end
    end
    return false,"stopped"
end
local function doPlacement(id,recT)
    collapseReplayMenu(true)
    local info=data.places[tostring(id)]
    if not info then return false,"unknown placement #"..tostring(id) end
    local folder=workspace:FindFirstChild("Troops")
    if not folder then return false,"Workspace.Troops missing" end
    local remote,remoteErr=directRemote()
    if not remote then return false,remoteErr end
    local unitType=info.unit
    local wantedModel=modelNames[unitType]
    if not wantedModel then return false,"unknown unit type "..tostring(unitType) end
    local goal=Vector3.new(info.pos[1],info.pos[2],info.pos[3])

    local function nativeCalibrate(reason,disableDirect)
        if not sessionHookReady then
            return false,"native calibration requires hook: "..tostring(sessionHookError)
        end
        say("NATIVE TYPE CALIBRATION #"..id,unitType.." | "..tostring(reason))
        local captureBefore=#observedPlaceCalls
        -- A native click is needed only when the troop type is uncalibrated
        -- or when a direct request is rejected. This reuses the previously
        -- successful recorded-camera placement routine.
        calibrationRotationPending=(directRotations[id] or 1)-1
        bindCamera()
        local ok,why=doCalibrationPlacement(id,recT)
        unbindCamera()
        calibrationRotationPending=0
        if not ok then return false,"native placement failed: "..tostring(why) end
        local model=placedModels[id]
        if not model then return false,"native click reported success but no model bound" end
        local captured,captureDrift=findObservedPlaceSince(captureBefore,model)
        if not captured then
            -- Never guess an opcode or troop name from the model name.
            return false,"native troop spawned but its BridgeNet2 payload was not captured"
        end
        local pivot=modelPos(model)
        local yDelta=pivot and (captured.pos.Y-pivot.Y) or 0
        if math.abs(yDelta)>2 then
            return false,"captured Y offset implausible: "..tostring(yDelta)
        end
        local expectedRotation=directRotations[id] or 1
        local rotationShift=(captured.rotation-expectedRotation)%4
        sessionPlaceProfiles[unitType]={
            code=captured.code, remoteName=captured.name,
            yDelta=yDelta, rotationShift=rotationShift,
            nativeOnly=(disableDirect==true),
        }
        if not sessionPlaceCode then sessionPlaceCode=captured.code end
        say("TYPE PROFILE LEARNED "..unitType,
            "code="..tostring(captured.code).." serverName="..tostring(captured.name)
            .." | deltaY="..string.format("%.3f",yDelta)
            .." rot="..tostring(captured.rotation)
            .." shift="..tostring(rotationShift)
            .." inputDrift="..string.format("%.2f",captureDrift or -1)
            .." | "..(disableDirect and "NATIVE ONLY" or "DIRECT NEXT"))
        return true
    end

    -- Never reuse the Pumpkin Farmer template blindly for Chef/Medic.
    local profile=sessionPlaceProfiles[unitType]
    if not profile then
        return nativeCalibrate("FIRST OF TYPE; learn actual name/Y/rotation/opcode",false)
    end
    if profile.nativeOnly then
        return nativeCalibrate("this troop type rejected direct placement earlier",true)
    end

    local baselineAll={}
    for _,m in ipairs(folder:GetChildren()) do
        if m:IsA("Model") then baselineAll[m]=true end
    end
    local function accept(model,drift)
        placedModels[id]=model
        placedTimes[id]=os.clock()
        selectedPreview=nil
        rotationsSinceSelection=0
        say("DIRECT PLACED #"..id,wantedModel
            .." | drift="..string.format("%.2f",drift or 0).." studs")
        return true
    end
    local cashLogAt=0
    while not stopped do
        local found,issue,dist=freshPlacedTroop(baselineAll,unitType,goal)
        if issue then return false,"DIRECT PLACE SAFETY #"..id..": "..issue end
        if found then return accept(found,dist) end
        local money=cashOnHud(nil)
        local cost=CONFIG.placeCost[unitType]
        if cost and (money==nil or money<cost) then
            if os.clock()-cashLogAt>5 then
                say("WAIT CASH DIRECT #"..id,wantedModel.." "
                    ..(money and ("$"..money.."/$"..cost) or "money HUD not ready"))
                cashLogAt=os.clock()
            end
            delayCheck(.35)
        else
            local requestPoint=Vector3.new(goal.X,goal.Y+profile.yDelta,goal.Z)
            local rotation=((directRotations[id] or 1)-1+profile.rotationShift)%4+1
            say("DIRECT TYPE PLACE #"..id,
                string.format("type=%s sendName=%s code=%s xyz=(%.2f,%.3f,%.2f) rot=%d cash=%s",
                    unitType,profile.remoteName,profile.code,
                    requestPoint.X,requestPoint.Y,requestPoint.Z,rotation,tostring(money)))
            local ok,err=pcall(function()
                remote:FireServer({{profile.remoteName,requestPoint,rotation},profile.code})
            end)
            if not ok then return false,"direct FireServer failed: "..tostring(err) end
            local deadline=os.clock()+4.2
            while not stopped and os.clock()<deadline do
                local spawned,spawnErr,spawnDist=freshPlacedTroop(baselineAll,unitType,goal)
                if spawnErr then return false,"DIRECT PLACE SAFETY #"..id..": "..spawnErr end
                if spawned then return accept(spawned,spawnDist) end
                delayCheck(.18)
            end
            -- Do not repeat a rejected FireServer and spam Error 002.
            -- Allow late replication to finish before switching to native GUI.
            if not delayCheck(1.2) then return false,"stopped" end
            local late,lateErr,lateDist=freshPlacedTroop(baselineAll,unitType,goal)
            if lateErr then return false,"DIRECT PLACE SAFETY #"..id..": "..lateErr end
            if late then return accept(late,lateDist) end
            local rejection=placementErrorText()
            say("DIRECT REJECTED #"..id,
                "no new "..wantedModel.." model | "..tostring(rejection or "server did not spawn troop")
                .." | switching this TYPE to native calibrated placement")
            -- Once a type fails direct, keep it in native mode for this match.
            -- This is slower, but avoids repeated Error 002 and missed defense.
            return nativeCalibrate("DIRECT REJECTED; one safe GUI recovery",true)
        end
    end
    return false,"stopped"
end
local function aimAndOpen(model,id,t)
    if not model or not model.Parent then return false,"placed unit disappeared" end
    local pos=modelPos(model)
    if not pos then return false,"missing model pivot" end
    local info=data.places[tostring(id)]
    local anchor=data.anchors[tostring(id)]
    freeze(t)
    if anchor and anchor.cam then
        local cf=cframeFrom(anchor.cam)
        if cf then cameraOverride=cf; workspace.CurrentCamera.CFrame=cf end
    end
    task.wait(.07)
    local x,y=project(pos)
    if not x then
        local c=workspace.CurrentCamera
        cameraOverride=CFrame.lookAt(c.CFrame.Position,pos)
        c.CFrame=cameraOverride
        task.wait(.07)
        x,y=project(pos)
    end
    if not x then return false,"model is outside camera" end
    local ok,why=tap(x,y)
    if not ok then return false,tostring(why) end
    return true
end
local function findSignalButton(button)
    if not button then return nil end
    if type(firesignal)~="function" then return nil,"firesignal not available" end
    if type(getconnections)=="function" then
        local success,conns=pcall(getconnections,button.Activated)
        if success and type(conns)=="table" and #conns==0 then
            return nil,"Activated has no connections"
        end
    end
    return button
end
-- Upgrade: the capture with two model-target N calls and one empty o call
-- does NOT prove that N upgrades anything. Use the previously successful
-- InspectMenu Activated route until we can calibrate the actual upgrade action.
local function guardedUpgrade(id,before,after,recT)
    collapseReplayMenu(true)
    local info=data.places[tostring(id)]
    local m=placedModels[id]
    if not m or not m.Parent then return false,"unit #"..id.." missing" end
    -- v0.7: no per-unit recorded timing gate here. On reaching an upgrade action,
    -- select this specific unit and send Activated at the first affordable moment.
    -- Keep actions sequential: money / sleeping unit can delay but never skip a step.
    if stopped then return false,"stopped" end
    local lastLog,tries,signalAttempts=0,0,0
    local signalSentAt=nil
    local lastCashObserved=nil
    local lastCashChange=os.clock()
    local cashStallReported=false
    -- Force selection of the recorded *instance* before reading the GUI.
    -- A stale InspectMenu for a different copy must never be trusted.
    local opened,openWhy=aimAndOpen(m,id,recT)
    if not opened then log("Initial selection attempt: "..tostring(openWhy)) end
    delayCheck(.25)
    say("UPGRADE PENDING #"..id,info.unit.." Lv"..before.." -> "..after.."; waiting until awake")
    while not stopped do
        local state,why=inspect(info.unit)
        local observed=modelLevel(m)
        if observed and observed>after then return false,"unit level skipped target: model reads Lv"..observed end
        if observed and observed~=before and observed~=after then
            return false,"target model level mismatch: model Lv"..observed..", expected "..before
        end
        if observed==after and not signalSentAt then
            return false,"target model reached Lv"..after
                .." without this script confirming an upgrade signal; STOPPED to avoid losing unit identity"
        end
        if observed==after then
            say("UPGRADE CONFIRMED #"..id,info.unit.." Lv"..before.." -> "..after.." (model)")
            cameraFrozen=nil
            cameraOverride=nil
            return true
        end
        if state and state.level==after and signalSentAt and (not observed or observed==after) then
            say("UPGRADE CONFIRMED #"..id,info.unit.." Lv"..before.." -> "..after.." (InspectMenu)")
            cameraFrozen=nil
            cameraOverride=nil
            return true
        end
        if state and state.level>after then
            return false,"inspect menu level is beyond expected Level "..after.."; wrong model or recording mismatch"
        end
        if state and state.level==before then
            local cash=cashOnHud(state.root)
            if cash~=nil then
                if cash~=lastCashObserved then
                    lastCashObserved=cash
                    lastCashChange=os.clock()
                    cashStallReported=false
                elseif cash<state.cost and not cashStallReported
                    and os.clock()-lastCashChange>=30 then
                    log("ECONOMY STALLED #"..id.." | money $"..cash.." / $"..state.cost
                        .." unchanged 30s; not skipping upgrade; checking match result")
                    cashStallReported=true
                end
            end
            if cash~=nil and cash>=state.cost then
                if not signalSentAt or os.clock()-signalSentAt>=CONFIG.afterSignalWait then
                    if signalAttempts>=CONFIG.maxUpgradeSignalAttempts then
                        return false,"Upgrade not confirmed after "..signalAttempts.." verified Activated attempts"
                    end
                    local button,reason=findSignalButton(state.button)
                    if not button then return false,reason end
                    signalAttempts=signalAttempts+1
                    local fired,err=pcall(function() firesignal(button.Activated,nil,1) end)
                    if not fired then return false,"firesignal failed: "..tostring(err) end
                    signalSentAt=os.clock()
                    say("ACTIVATED #"..id.." attempt "..signalAttempts,"waiting for actual Level increase")
                    delayCheck(.35)
                else delayCheck(.17) end
            else
                if os.clock()-lastLog>CONFIG.sleepLogSeconds then
                    say("WAIT MONEY/WAKE #"..id,info.unit.." "..(cash and ("$"..cash.."/$"..state.cost) or "money unreadable"))
                    lastLog=os.clock()
                end
                delayCheck(.35)
            end
        elseif state and state.level~=before then
            -- State changes without our signal mean a different model may be selected.
            if os.clock()-lastLog>CONFIG.sleepLogSeconds then
                say("WAIT CORRECT INSTANCE #"..id,"expected Lv"..before..", menu Lv"..state.level)
                lastLog=os.clock()
            end
            aimAndOpen(m,id,recT)
            delayCheck(CONFIG.selectRetrySeconds)
        else
            if os.clock()-lastLog>CONFIG.sleepLogSeconds then
                say("WAIT UNIT AWAKE #"..id,info.unit.." | "..tostring(why))
                lastLog=os.clock()
            end
            local okSelect,selectWhy=aimAndOpen(m,id,recT)
            if not okSelect and os.clock()-lastLog>CONFIG.sleepLogSeconds then
                log("auto select: "..tostring(selectWhy))
            end
            delayCheck(CONFIG.selectRetrySeconds)
        end
    end
    return false,"stopped"
end

